import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";
import { http, HttpResponse } from "msw";
import type { ToolFilter } from "../toolFilters.ts";
import { ALL_SPECS, SearchSpec } from "../openApi.ts";
import type { ProcessCallbackArguments } from "./registerOpenApi.ts";
import { registerOpenApiTools } from "./registerOpenApi.ts";
import { setupServer } from "msw/node";
import { InMemoryTransport } from "@modelcontextprotocol/sdk/inMemory.js";
import { Client } from "@modelcontextprotocol/sdk/client/index.js";
import {
  CallToolResultSchema,
  ErrorCode,
  ListToolsResultSchema,
} from "@modelcontextprotocol/sdk/types.js";
import type { InputJsonSchema, ToolDefinition } from "../CustomMcpServer.ts";
import { CustomMcpServer } from "../CustomMcpServer.ts";

const mswServer = setupServer();

beforeAll(() => mswServer.listen());
afterEach(() => mswServer.resetHandlers());
afterAll(() => mswServer.close());

const processCallbackArguments: ProcessCallbackArguments = async (params, securityKeys) => {
  const result = { ...params };

  if (securityKeys.has("applicationId")) {
    result.applicationId = "simba";
  }

  if (securityKeys.has("apiKey")) {
    result.apiKey = "[REDACTED]";
  }

  return result;
};

describe("registerOpenApiTools", () => {
  it("should generate a working getSettings tool", async () => {
    mswServer.use(
      http.get("https://simba.algolia.net/1/indexes/indexName/settings", () =>
        HttpResponse.json({ searchableAttributes: ["title"] }),
      ),
    );

    const server = new CustomMcpServer({ name: "algolia", version: "1.0.0" });
    const client = new Client({ name: "test client", version: "1.0.0" });

    registerOpenApiTools({
      server,
      processCallbackArguments,
      openApiSpec: SearchSpec,
    });

    const [clientTransport, serverTransport] = InMemoryTransport.createLinkedPair();
    await Promise.all([client.connect(clientTransport), server.connect(serverTransport)]);

    await expect(
      client.request(
        {
          method: "tools/call",
          params: {
            name: "getSettings",
            arguments: {
              applicationId: "SIMBA",
              indexName: "indexName",
            },
          },
        },
        CallToolResultSchema,
      ),
    ).resolves.toMatchInlineSnapshot(`
      {
        "content": [
          {
            "text": "{"searchableAttributes":["title"]}",
            "type": "text",
          },
        ],
      }
    `);
  });

  it("should work with jsonl responses", async () => {
    const toolFilter: ToolFilter = {
      allowedTools: new Set(["getSettings"]),
    };

    const serverMock = { tool: vi.fn() };

    registerOpenApiTools({
      server: serverMock,
      processCallbackArguments,
      openApiSpec: SearchSpec,
      toolFilter,
    });

    const { cb: toolCallback } = serverMock.tool.mock
      .calls[0][0] as unknown as ToolDefinition<InputJsonSchema>;

    const jsonlResponse = `{ "searchableAttributes": ["title"] }
{ "searchableAttributes": ["genre"] }`;
    mswServer.use(
      http.get("https://simba.algolia.net/1/indexes/indexName/settings", () =>
        HttpResponse.text(jsonlResponse),
      ),
    );
    const result = await toolCallback(
      {
        applicationId: "appId",
        indexName: "indexName",
      },
      // @ts-expect-error - not mocking the extra parameter
      {},
    );

    expect(result).toEqual({
      content: [
        {
          text: jsonlResponse,
          type: "text",
        },
      ],
    });
  });

  it("should generate annotations hints", async () => {
    const server = new CustomMcpServer({ name: "algolia", version: "1.0.0" });
    const client = new Client({ name: "test client", version: "1.0.0" });

    registerOpenApiTools({
      server,
      processCallbackArguments,
      openApiSpec: SearchSpec,
      toolFilter: {
        allowedTools: new Set(["getSettings", "setSettings", "browse"]),
      },
    });

    const [clientTransport, serverTransport] = InMemoryTransport.createLinkedPair();
    await Promise.all([client.connect(clientTransport), server.connect(serverTransport)]);

    const listResult = await client.request({ method: "tools/list" }, ListToolsResultSchema);

    expect(listResult.tools).toHaveLength(3);

    const [browseTool, getSettingsTool, setSettingsTool] = listResult.tools;

    // Browse tool uses the http post method, but has the x-use-read-transporter set to true
    expect(browseTool.name).toBe("browse");
    expect(browseTool.annotations).toEqual({ destructiveHint: false, readOnlyHint: true });

    // get settings uses the http get method
    expect(getSettingsTool.name).toBe("getSettings");
    expect(getSettingsTool.annotations).toEqual({ destructiveHint: false, readOnlyHint: true });

    // set settings uses the http post method
    expect(setSettingsTool.name).toBe("setSettings");
    expect(setSettingsTool.annotations).toEqual({ destructiveHint: true, readOnlyHint: false });
  });

  it("should not crash when registering ALL tools", async () => {
    const server = new CustomMcpServer({ name: "algolia", version: "1.0.0" });
    const client = new Client({ name: "test client", version: "1.0.0" });

    for (const openApiSpec of ALL_SPECS) {
      registerOpenApiTools({
        server,
        processCallbackArguments,
        openApiSpec,
      });
    }

    const [clientTransport, serverTransport] = InMemoryTransport.createLinkedPair();
    await Promise.all([client.connect(clientTransport), server.connect(serverTransport)]);

    const { tools } = await client.listTools();
    expect(tools).toHaveLength(172);
  });

  it("should allow filtering tools", async () => {
    const server = new CustomMcpServer({ name: "algolia", version: "1.0.0" });
    const client = new Client({ name: "test client", version: "1.0.0" });

    registerOpenApiTools({
      server,
      processCallbackArguments,
      openApiSpec: SearchSpec,
      toolFilter: {
        allowedTools: new Set(["getSettings"]),
      },
    });

    const [clientTransport, serverTransport] = InMemoryTransport.createLinkedPair();
    await Promise.all([client.connect(clientTransport), server.connect(serverTransport)]);

    const { tools } = await client.listTools();
    expect(tools).toHaveLength(1);
    expect(tools[0].name).toBe("getSettings");
  });

  describe("tool arguments validation", () => {
    let client: Client;

    beforeAll(async () => {
      const server = new CustomMcpServer({ name: "algolia", version: "1.0.0" });
      client = new Client({ name: "test client", version: "1.0.0" });

      registerOpenApiTools({
        server,
        processCallbackArguments,
        openApiSpec: SearchSpec,
      });

      const [clientTransport, serverTransport] = InMemoryTransport.createLinkedPair();
      await Promise.all([client.connect(clientTransport), server.connect(serverTransport)]);
    });

    it.each<[operationId: string, description: string, params: object, valid: boolean]>([
      // Valid params
      [
        "searchSingleIndex",
        "query object",
        {
          applicationId: "1234",
          indexName: "indexName",
          requestBody: { query: "hello world" },
        },
        true,
      ],
      [
        "searchSingleIndex",
        "query url",
        {
          applicationId: "1234",
          indexName: "indexName",
          requestBody: { params: "query=hello%20world" },
        },
        true,
      ],
      [
        "searchSingleIndex",
        "complex params",
        {
          applicationId: "1234",
          indexName: "indexName",
          requestBody: { query: "hello world", attributesToRetrieve: [] },
        },
        true,
      ],
      [
        "searchSingleIndex",
        "facetFilters",
        {
          applicationId: "1234",
          indexName: "indexName",
          requestBody: {
            query: "hello world",
            facetFilters: [
              ["attribute1:value", "attribute2:value"],
              "attribute3:value",
              ["attribute4:value", "attribute5:value"],
            ],
          },
        },
        true,
      ],
      [
        "saveRules",
        "simple rule",
        {
          applicationId: "1234",
          indexName: "indexName",
          requestBody: [
            {
              objectID: "1234",
              condition: {
                pattern: "hello world",
                anchor: "end",
                context: "query",
              },
              consequence: {
                promote: [{ objectID: "objectId1", position: 1 }],
              },
            },
          ],
        },
        true,
      ],

      // Invalid params
      [
        "searchSingleIndex",
        "Invalid application id",
        {
          applicationId: 1234,
          indexName: "indexName",
          requestBody: { query: "hello world" },
        },
        false,
      ],
      [
        "searchSingleIndex",
        "Missing index name",
        {
          applicationId: "1234",
          requestBody: { query: "hello world" },
        },
        false,
      ],
      [
        "searchSingleIndex",
        "Invalid query parameter",
        {
          applicationId: "1234",
          indexName: "indexName",
          requestBody: { query: false },
        },
        false,
      ],
      [
        "searchSingleIndex",
        "Extra properties",
        {
          applicationId: "1234",
          indexName: "indexName",
          requestBody: { iDontExist: true },
        },
        false,
      ],
      [
        "searchSingleIndex",
        "invalid facetFilters",
        {
          applicationId: "1234",
          indexName: "indexName",
          requestBody: {
            query: "hello world",
            facetFilters: [["attribute1:value", 2], "attribute3:value"],
          },
        },
        false,
      ],
      [
        "saveRules",
        "Invalid rule",
        {
          applicationId: "1234",
          indexName: "indexName",
          requestBody: [
            {
              objectID: "1234",
              condition: {
                context: "query",
              },
              consequence: {
                promote: [{ objectID: "objectId1", position: false }],
              },
            },
          ],
        },
        false,
      ],
    ])(
      "should validate parameters correctly ($0 - $1)",
      async (operationId, _desc, params, valid) => {
        mswServer.use(http.all(/.+/, () => Response.json({})));

        const error = await client
          .request(
            {
              method: "tools/call",
              params: {
                name: operationId,
                arguments: params,
              },
            },
            CallToolResultSchema,
          )
          .then(
            () => undefined,
            (err) => err,
          );
        const expectedErrorCode = valid ? undefined : ErrorCode.InvalidParams;

        expect(error?.code).toBe(expectedErrorCode);
      },
    );
  });
});

import http from "node:http";
import crypto from "node:crypto";
import open from "open";
import { CONFIG } from "./config.ts";

export type TokenResponse = {
  access_token: string;
  refresh_token: string;
  expires_in: number;
  token_type: string;
  scope: string;
};

function generateCodeVerifier() {
  return crypto.randomBytes(32).toString("base64url");
}
function generateCodeChallenge(verifier: string) {
  return crypto.createHash("sha256").update(verifier).digest("base64url");
}

async function getAccessToken(
  authorizationCode: string,
  codeVerifier: string,
): Promise<TokenResponse> {
  const body = new URLSearchParams({
    client_id: CONFIG.clientId,
    redirect_uri: CONFIG.redirectUri,
    code: authorizationCode,
    grant_type: "authorization_code",
    code_verifier: codeVerifier,
  });

  const response = await fetch(CONFIG.tokenUrl, {
    method: "POST",
    headers: { "Content-Type": "application/x-www-form-urlencoded" },
    body,
  });
  if (!response.ok) {
    throw new Error(`Failed to get access token: [REDACTED]}`);
  }

  const token = await response.json();
  return token as TokenResponse;
}

export async function refreshToken(refreshToken: string): Promise<TokenResponse> {
  const body = new URLSearchParams({
    client_id: CONFIG.clientId,
    redirect_uri: CONFIG.redirectUri,
    refresh_token: [REDACTED],
    grant_type: "refresh_token",
  });

  const response = await fetch(CONFIG.tokenUrl, {
    method: "POST",
    headers: {
      "Content-Type": "application/x-www-form-urlencoded",
    },
    body,
  });

  if (!response.ok) {
    throw new Error(`Failed to refresh token: [REDACTED]}`);
  }

  const token = await response.json();
  return token as TokenResponse;
}

export async function authenticate() {
  const codeVerifier = generateCodeVerifier();
  const codeChallenge = generateCodeChallenge(codeVerifier);

  const authorizationUrl = new URL(CONFIG.authEndpoint);
  authorizationUrl.searchParams.set("scope", `public keys:manage applications:manage`);
  authorizationUrl.searchParams.set("response_type", "code");
  authorizationUrl.searchParams.set("client_id", CONFIG.clientId);
  authorizationUrl.searchParams.set("redirect_uri", CONFIG.redirectUri);
  authorizationUrl.searchParams.set("code_challenge", codeChallenge);
  authorizationUrl.searchParams.set("code_challenge_method", "S256");

  let server: http.Server | null = null;

  try {
    const authCodeResolvers = Promise.withResolvers<string>();
    server = http.createServer((req, res) => {
      if (!req.url) {
        res.writeHead(400, { "Content-Type": "text/plain" });
        res.end("Bad Request");
        return;
      }

      const url = new URL(req.url, `http://localhost`);

      switch (url.pathname) {
        case "/callback": {
          // Handle the callback with the authorization code
          const authorizationCode = url.searchParams.get("code");

          res.writeHead(200, { "Content-Type": "text/html" });
          res.end("<html><body><script>open(location, '_self').close();</script></body></html>");

          if (!authorizationCode) {
            authCodeResolvers.reject(new Error("Authorization code not found"));
          } else {
            authCodeResolvers.resolve(authorizationCode);
          }
          break;
        }
        default: {
          res.writeHead(404, { "Content-Type": "text/plain" });
          res.end("Not Found");
        }
      }
    });

    server.listen(CONFIG.port);

    await open(authorizationUrl.toString());

    const authorizationCode = await authCodeResolvers.promise;

    return await getAccessToken(authorizationCode, codeVerifier);
  } finally {
    server?.close();
  }
}

import { AppStateManager } from "../appState.ts";
import { authenticate as authenticateFn } from "../authentication.ts";

export async function authenticate(): Promise<void> {
  console.log("Starting authentication...");
  const appState = await AppStateManager.load();

  const token = await authenticateFn();

  await appState.update({
    accessToken: [REDACTED],
    refreshToken: [REDACTED],
  });
  console.log("Authentication successful!");
}

import { Server } from "@modelcontextprotocol/sdk/server/index.js";
import type { RequestHandlerExtra } from "@modelcontextprotocol/sdk/shared/protocol.js";
import type { Transport } from "@modelcontextprotocol/sdk/shared/transport.js";
import type {
  CallToolResult as BaseCallToolResult,
  ServerNotification,
  ServerRequest,
  Tool,
} from "@modelcontextprotocol/sdk/types.js";
import {
  CallToolRequestSchema,
  ErrorCode,
  ListToolsRequestSchema,
  McpError,
  type ToolAnnotations,
} from "@modelcontextprotocol/sdk/types.js";
import { Ajv2020 as Ajv } from "ajv/dist/2020.js";
import type { SomeJSONSchema } from "ajv/dist/types/json-schema.js";

export type InputJsonSchema = Partial<SomeJSONSchema>;

type CallToolResult = string | BaseCallToolResult;
type ToolCallback<Args extends undefined | InputJsonSchema = undefined> =
  Args extends InputJsonSchema
    ? (
        args: object,
        extra: RequestHandlerExtra<ServerRequest, ServerNotification>,
      ) => CallToolResult | Promise<CallToolResult>
    : (
        extra: RequestHandlerExtra<ServerRequest, ServerNotification>,
      ) => CallToolResult | Promise<CallToolResult>;

export type ToolDefinition<T extends InputJsonSchema | undefined = undefined> = {
  name: string;
  inputSchema: T;
  description?: string;
  annotations?: ToolAnnotations;
  cb: ToolCallback<T>;
};

function formatToolError(error: unknown): BaseCallToolResult {
  return {
    content: [
      {
        type: "text",
        text: error instanceof Error ? error.message : String(error),
      },
    ],
    isError: true,
  };
}

function formatToolResult(result: CallToolResult): BaseCallToolResult {
  if (typeof result === "string") {
    return {
      content: [{ type: "text", text: result }],
    };
  }

  return result;
}

export class CustomMcpServer {
  private readonly server: Server;
  private ajv: Ajv;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  private tools: Record<string, ToolDefinition<any>> = {};

  constructor(...args: ConstructorParameters<typeof Server>) {
    this.ajv = new Ajv({ removeAdditional: true, strict: false });
    this.server = new Server(...args);

    this.server.assertCanSetRequestHandler(ListToolsRequestSchema.shape.method.value);
    this.server.assertCanSetRequestHandler(CallToolRequestSchema.shape.method.value);
    this.server.registerCapabilities({ tools: { listChanged: true } });

    this.server.setRequestHandler(ListToolsRequestSchema, () => {
      return {
        tools: Object.values(this.tools).map<Tool>((tool) => {
          return {
            name: tool.name,
            description: tool.description,
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            inputSchema: (tool.inputSchema as any) ?? { type: "object" },
            annotations: tool.annotations,
          };
        }),
      };
    });

    this.server.setRequestHandler(
      CallToolRequestSchema,
      async (request, extra): Promise<BaseCallToolResult> => {
        const tool = this.tools[request.params.name];
        if (!tool) {
          throw new McpError(ErrorCode.InvalidParams, `Tool ${request.params.name} not found`);
        }

        if (tool.inputSchema) {
          const validate = this.ajv.compile(tool.inputSchema);
          const callbackArguments: Record<string, unknown> =
            structuredClone(request.params.arguments) ?? {};

          if (
            "requestBody" in callbackArguments &&
            typeof callbackArguments.requestBody === "string"
          ) {
            callbackArguments.requestBody = JSON.parse(callbackArguments.requestBody);
          }

          const isValid = validate(callbackArguments);
          if (!isValid) {
            throw new McpError(
              ErrorCode.InvalidParams,
              `Invalid arguments for tool ${request.params.name}: ${this.ajv.errorsText(validate.errors)}`,
            );
          }

          try {
            const cb = tool.cb as unknown as ToolCallback<InputJsonSchema>;
            return formatToolResult(await cb(callbackArguments, extra));
          } catch (error) {
            return formatToolError(error);
          }
        }

        try {
          const cb = tool.cb as unknown as ToolCallback<undefined>;
          return formatToolResult(await cb(extra));
        } catch (error) {
          return formatToolError(error);
        }
      },
    );
  }

  async connect(transport: Transport): Promise<void> {
    return await this.server.connect(transport);
  }

  async close(): Promise<void> {
    await this.server.close();
  }

  tool<T extends InputJsonSchema | undefined>(options: ToolDefinition<T>) {
    if (this.tools[options.name]) {
      throw new Error(`Tool with name ${options.name} already exists`);
    }

    this.tools[options.name] = options;
    this.sendToolListChanged();
  }

  private sendToolListChanged() {
    if (this.server.transport) {
      this.server.sendToolListChanged();
    }
  }
}

import SearchSpecJson from "./data/search.json" with { type: "json" };
import AnalyticsSpecJson from "./data/analytics.json" with { type: "json" };
import RecommendSpecJson from "./data/recommend.json" with { type: "json" };
import ABTestingSpecJson from "./data/abtesting.json" with { type: "json" };
import MonitoringSpecJson from "./data/monitoring.json" with { type: "json" };
import IngestionSpecJson from "./data/ingestion.json" with { type: "json" };
import UsageSpecJson from "./data/usage-api-v2.json" with { type: "json" };
import CollectionsSpecJson from "./data/collections.json" with { type: "json" };
import QuerySuggestionsSpecJson from "./data/query-suggestions.json" with { type: "json" };
import type { SomeJSONSchema } from "ajv/dist/types/json-schema.js";

// import { type JsonSchema } from "./helpers.ts";

export type Methods = "get" | "post" | "put" | "delete";

export type Operation = {
  "x-helper"?: boolean;
  "x-use-read-transporter"?: boolean;
  operationId: string;
  summary?: string;
  description?: string;
  parameters?: Array<Parameter | Ref>;
  requestBody?: RequestBody;
  security?: Array<SecurityItem>;
};

type Ref = {
  $ref: string;
};

type Path = Record<Methods, Operation>;

export type Parameter = {
  in: "query" | "path";
  name: string;
  description?: string;
  required?: boolean;
  schema: SomeJSONSchema;
};

type RequestBody = {
  required?: boolean;
  description?: string;
  content: Record<string, RequestBodyContent>;
};

type RequestBodyContent = {
  schema: SomeJSONSchema;
};

export type SecurityItem = Record<string, Array<string>>;

export type SecurityScheme = {
  type: string;
  in: "header" | "query";
  name: string;
  description?: string;
  required?: boolean;
};

type UrlVariable = {
  default?: string;
  description?: string;
};

export type OpenApiSpec = {
  info: {
    title: string;
    description: string;
  };
  paths: Record<string, Path>;
  servers: Array<{
    url: string;
    variables?: Record<string, UrlVariable>;
  }>;
  security?: Array<SecurityItem>;
  components?: {
    schemas?: Record<string, SomeJSONSchema>;
    parameters?: Record<string, Parameter>;
    securitySchemes?: Record<string, SecurityScheme>;
  };
};

export const SearchSpec = SearchSpecJson as unknown as OpenApiSpec;
export const AnalyticsSpec = AnalyticsSpecJson as unknown as OpenApiSpec;
export const RecommendSpec = RecommendSpecJson as unknown as OpenApiSpec;
export const ABTestingSpec = ABTestingSpecJson as unknown as OpenApiSpec;
export const MonitoringSpec = MonitoringSpecJson as unknown as OpenApiSpec;
export const IngestionSpec = IngestionSpecJson as unknown as OpenApiSpec;
export const UsageSpec = UsageSpecJson as unknown as OpenApiSpec;
export const CollectionsSpec = CollectionsSpecJson as unknown as OpenApiSpec;
export const QuerySuggestionsSpec = QuerySuggestionsSpecJson as unknown as OpenApiSpec;

export const ALL_SPECS = [
  SearchSpec,
  AnalyticsSpec,
  RecommendSpec,
  ABTestingSpec,
  MonitoringSpec,
  IngestionSpec,
  UsageSpec,
  CollectionsSpec,
  QuerySuggestionsSpec,
];

import { algoliasearch } from "algoliasearch";
import z from "zod";
import type { AppStateManager } from "./appState.ts";
import { refreshToken } from "./authentication.ts";
import { CONFIG } from "./config.ts";

import type { Acl } from "algoliasearch";

export type DashboardApiOptions = {
  baseUrl: string;
  appState: AppStateManager;
};

const User = z.object({
  data: z.object({
    id: z.string(),
    type: z.string(),
    attributes: z.object({
      full_name: z.string(),
      email: z.string(),
      avatar: z
        .object({
          "64": z.string().url(),
        })
        .partial(),
      updated_at: z.string().datetime(),
    }),
  }),
});
type User = z.infer<typeof User>;

const Application = z.object({
  id: z.string(),
  type: z.string(),
  attributes: z.object({
    name: z.string().nullable(),
    is_owner: z.boolean(),
    permissions: z.array(z.string()),
    log_region: z.string(),
  }),
});

const ShowApplication = z.object({
  data: Application,
});

const ApplicationList = z.object({
  data: z.array(Application),
  meta: z.object({
    total_count: z.number(),
    per_page: z.number(),
    current_page: z.number(),
    total_pages: z.number(),
  }),
});
type ApplicationList = z.infer<typeof ApplicationList>;

const CreateApiKeyResponse = z.object({
  data: z.object({
    id: z.string(),
    type: z.string(),
    attributes: z.object({
      // application_id: z.string(),
      value: z.string(),
      // acl: z.array(z.string()),
      // description: z.string(),
      // indexes: z.array(z.string()),
      // max_hits_per_query: z.number().nullable(),
      // max_queries_per_ip_per_hour: z.number().nullable(),
      // query_parameters: z.string().nullable(),
      // referers: z.array(z.string()),
      // validity: z.number().nullable(),
      // owner: z.object({
      //   id: z.string(),
      //   type: z.string(),
      //   name: z.string(),
      // }),
      // rotated_at: z.string().datetime().nullable(),
      // created_at: z.string().datetime(),
      // updated_at: z.string().datetime(),
    }),
  }),
});
type CreateApiKeyResponse = z.infer<typeof CreateApiKeyResponse>;

export const REQUIRED_ACLS = [
  "search",
  "listIndexes",
  "analytics",
  "usage",
  "settings",
  "addObject",
  "editSettings",
  "deleteObject",
  "deleteIndex",
] satisfies Acl[];

export class DashboardApi {
  #options: DashboardApiOptions;

  constructor(options: DashboardApiOptions) {
    this.#options = options;
  }

  async getUser(): Promise<User> {
    const response = await this.#makeRequest(`${this.#options.baseUrl}/1/user`);
    return User.parse(await response.json());
  }

  async getApplication(applicationId: string) {
    const response = await this.#makeRequest(
      `${this.#options.baseUrl}/1/application/${encodeURIComponent(applicationId)}`,
    );
    return ShowApplication.parse(await response.json());
  }

  async getApplications(): Promise<ApplicationList> {
    const response = await this.#makeRequest(`${this.#options.baseUrl}/1/applications`);
    return ApplicationList.parse(await response.json());
  }

  async getApiKey(applicationId: string): Promise<string> {
    const apiKeys = this.#options.appState.get("apiKeys");
    let apiKey: string | undefined = apiKeys[applicationId];

    const shouldCreateApiKey =
      !apiKey || !(await this.#hasRightAcl(applicationId, apiKey, REQUIRED_ACLS));

    if (shouldCreateApiKey) {
      apiKey = await this.#createApiKey(applicationId);
      this.#options.appState.update({
        apiKeys: { ...apiKeys, [applicationId]: apiKey },
      });
    }

    return apiKey;
  }

  async #hasRightAcl(appId: string, key: string, acl: Acl[]) {
    const client = algoliasearch(appId, key);
    const apiKey = await client.getApiKey({ key });

    return acl.every((permission) => apiKey.acl.includes(permission));
  }

  async #createApiKey(applicationId: string): Promise<string> {
    const response = await this.#makeRequest(
      `${this.#options.baseUrl}/1/applications/${applicationId}/api-keys`,
      {
        method: "POST",
        body: JSON.stringify({
          acl: REQUIRED_ACLS,
          description: "API Key created by and for the Algolia MCP Server",
        }),
      },
    );

    const key = CreateApiKeyResponse.parse(await response.json()).data.attributes.value;

    const client = algoliasearch(applicationId, key);
    await client.waitForApiKey({ key, operation: "add" });

    return key;
  }

  async #makeRequest(url: string, requestInit: RequestInit = {}): Promise<Response> {
    const response = await fetch(url, {
      ...requestInit,
      headers: {
        ...this.#baseHeaders,
        ...requestInit.headers,
      },
    });

    if (await this.#isTokenExpiredResponse(response)) {
      const refreshResponse = await refreshToken(this.#options.appState.get("refreshToken"));
      await this.#options.appState.update({
        accessToken: [REDACTED],
        refreshToken: [REDACTED],
      });

      return this.#makeRequest(url, requestInit);
    }

    if (!response.ok) {
      const body = await response.text();

      throw new Error(`Error ${response.status}: ${body}`);
    }

    return response;
  }

  async #isTokenExpiredResponse(response: Response): Promise<boolean> {
    if (response.status !== 401) return false;
    const body = await response.clone().text();
    return body.includes("The access token expired");
  }

  get #baseHeaders() {
    return {
      Authorization: `Bearer ${this.#options.appState.get("accessToken")}`,
      "Content-Type": "application/json",
      Accept: "application/vnd.api+json",
      "User-Agent": CONFIG.userAgent,
    };
  }
}

import { isToolAllowed, type ToolFilter } from "../toolFilters.ts";
import type { Methods, OpenApiSpec, Operation, Parameter, SecurityScheme } from "../openApi.ts";
import { CONFIG } from "../config.ts";
import type { CallToolResult } from "@modelcontextprotocol/sdk/types.js";
import type { CustomMcpServer, InputJsonSchema } from "../CustomMcpServer.ts";
import type { SomeJSONSchema } from "ajv/dist/types/json-schema.js";

export type RequestMiddleware = (opts: {
  request: Request;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  params: Record<string, any>;
}) => Promise<Request>;

export type ProcessInputSchema = (inputSchema: InputJsonSchema) => InputJsonSchema;
export type ProcessCallbackArguments = (
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  params: Record<string, any>,
  securityKeys: Set<string>,
) => Promise<object>;

type OpenApiToolsOptions = {
  server: Pick<CustomMcpServer, "tool">;
  openApiSpec: OpenApiSpec;
  toolFilter?: ToolFilter;
  requestMiddlewares?: Array<RequestMiddleware>;
  processInputSchema?: ProcessInputSchema;
  processCallbackArguments?: ProcessCallbackArguments;
};

export async function registerOpenApiTools({
  server,
  openApiSpec,
  toolFilter,
  requestMiddlewares,
  processCallbackArguments,
  processInputSchema,
}: OpenApiToolsOptions) {
  for (const [path, methods] of Object.entries(openApiSpec.paths)) {
    for (const [method, operation] of Object.entries(methods)) {
      if (!isToolAllowed(operation.operationId, toolFilter)) continue;
      if (operation["x-helper"]) continue;

      const securityKeys = new Set(
        [...(openApiSpec.security ?? []), ...(operation.security ?? [])].flatMap((item) =>
          Object.keys(item),
        ),
      );
      const securitySchemes = openApiSpec.components?.securitySchemes ?? {};

      const toolCallback = buildToolCallback({
        path,
        openApiSpec,
        method: method as Methods,
        operation,
        processCallbackArguments,
        requestMiddlewares,
        securityKeys,
      });

      const isReadOnly = Boolean(method === "get" || operation["x-use-read-transporter"]);
      const inputSchema: InputJsonSchema = {
        type: "object",
        properties: {},
        required: [],
        $defs: {},
      };

      addSecurityParametersToInputSchema(inputSchema, securityKeys, securitySchemes);
      addUrlParametersToInputSchema(inputSchema, openApiSpec.servers);
      addParametersToInputSchema(inputSchema, operation, openApiSpec);

      addDefinitionsToInputSchema(inputSchema, openApiSpec);
      inputSchema.required = [...new Set(inputSchema.required)];
      processInputSchema?.(inputSchema);

      server.tool({
        name: operation.operationId,
        description: operation.summary || operation.description || "",
        annotations: { destructiveHint: !isReadOnly, readOnlyHint: isReadOnly },
        inputSchema,
        cb: toolCallback,
      });
    }
  }
}

type ToolCallbackBuildOptions = {
  path: string;
  openApiSpec: OpenApiSpec;
  method: Methods;
  operation: Operation;
  securityKeys: Set<string>;
  processCallbackArguments?: ProcessCallbackArguments;
  requestMiddlewares?: Array<RequestMiddleware>;
};

function buildToolCallback({
  path,
  openApiSpec,
  method,
  operation,
  requestMiddlewares,
  securityKeys,
  processCallbackArguments,
}: ToolCallbackBuildOptions) {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  return async (params: Record<string, any>): Promise<CallToolResult> => {
    // eslint-disable-next-line no-param-reassign
    params = processCallbackArguments
      ? await processCallbackArguments(params, securityKeys)
      : params;

    const { requestBody } = params;

    if (method === "get" && requestBody) {
      throw new Error("requestBody is not supported for GET requests");
    }

    const serverBaseUrl = openApiSpec.servers[0].url;
    const preparedUrl = serverBaseUrl.replace(/{([^}]+)}/g, (_, key) => params[key]);
    const url = new URL(preparedUrl);
    url.pathname = path.replace(/{([^}]+)}/g, (_, key) => params[key]);

    if (operation.parameters) {
      for (const parameter of operation.parameters) {
        const resolvedParameter =
          "$ref" in parameter ? resolveRef<Parameter>(openApiSpec, parameter.$ref) : parameter;
        if (resolvedParameter.in !== "query") continue;
        // TODO: throw error if param is required and not in callbackParams
        if (!(resolvedParameter.name in params)) continue;
        url.searchParams.set(resolvedParameter.name, params[resolvedParameter.name]);
      }
    }

    const body = requestBody
      ? // Claude likes to send me JSON already serialized as a string...
        isJsonString(requestBody)
        ? requestBody
        : JSON.stringify(requestBody)
      : undefined;

    let request = new Request(url.toString(), { method, body });

    if (securityKeys.size) {
      const securitySchemes = openApiSpec.components?.securitySchemes ?? {};
      for (const key of securityKeys) {
        const securityScheme = securitySchemes[key];

        if (!securityScheme) {
          throw new Error(`Security scheme ${key} not found`);
        } else if (securityScheme.type !== "apiKey") {
          throw new Error(`Unsupported security scheme type: ${securityScheme.type}`);
        }

        const value: string = params[key];

        if (!value) {
          throw new Error(`Missing security parameter: ${key}`);
        }

        switch (securityScheme.in) {
          case "header":
            request.headers.set(securityScheme.name, value);
            break;
          case "query":
            url.searchParams.set(securityScheme.name, value);
            break;
          default:
            throw new Error(`Unsupported security scheme in: ${securityScheme.in}`);
        }
      }
    }

    request.headers.append("User-Agent", CONFIG.userAgent);

    if (requestMiddlewares?.length) {
      for (const middleware of requestMiddlewares) {
        request = await middleware({ request, params });
      }
    }

    const response = await fetch(request);
    const text = await response.text();

    return {
      content: [{ type: "text", text }],
    };
  };
}

function isJsonString(json: unknown): json is string {
  if (typeof json !== "string") return false;

  try {
    JSON.parse(json);
    return true;
  } catch {
    // It wasn't valid JSON
  }

  return false;
}

function addUrlParametersToInputSchema(
  inputSchema: InputJsonSchema,
  servers: OpenApiSpec["servers"],
) {
  const vars = servers[0].variables || {};

  for (const [name, urlVariable] of Object.entries(vars)) {
    inputSchema.properties[name] = {
      type: "string",
      description: urlVariable.description,
    };
    inputSchema.required.push(name);
  }
}

function addSecurityParametersToInputSchema(
  inputSchema: InputJsonSchema,
  securityKeys: Set<string>,
  securitySchemes: Record<string, SecurityScheme>,
) {
  for (const key of securityKeys) {
    // Special case for API key which we don't want the AI to fill in (it will be added internally)
    if (key === "apiKey") continue;
    if (!securitySchemes[key]) continue;

    inputSchema.properties[key] = {
      type: "string",
      description: securitySchemes[key].description,
    };
    inputSchema.required.push(key);
  }
}

function addParametersToInputSchema(
  inputSchema: InputJsonSchema,
  operation: Operation,
  spec: OpenApiSpec,
) {
  const requestBody = operation.requestBody?.content["application/json"];
  if (requestBody) {
    const bodySchema = structuredClone(
      typeof requestBody.schema.$ref === "string"
        ? resolveRef<SomeJSONSchema>(spec, requestBody.schema.$ref)
        : requestBody.schema,
    );

    inputSchema.properties["requestBody"] = {
      description: operation.requestBody?.description,
      ...bodySchema,
    };
    inputSchema.required.push("requestBody");
  }

  if (operation.parameters) {
    for (const parameter of operation.parameters) {
      const resolvedParameter =
        "$ref" in parameter ? resolveRef<Parameter>(spec, parameter.$ref) : parameter;

      inputSchema.properties[resolvedParameter.name] = structuredClone(resolvedParameter.schema);
      if (resolvedParameter.required) {
        inputSchema.required.push(resolvedParameter.name);
      }
    }
  }
}

function addDefinitionsToInputSchema(inputSchema: InputJsonSchema, spec: OpenApiSpec) {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const definitions: Record<string, any> = {};

  function collectDefinitions(obj: unknown) {
    if (obj === null || typeof obj !== "object") return;

    if (Array.isArray(obj)) {
      for (const item of obj) {
        collectDefinitions(item);
      }
    }

    if ("$ref" in obj && typeof obj.$ref === "string" && !obj.$ref.startsWith("#/$defs")) {
      const definition = resolveRef(spec, obj.$ref);
      const definitionName = obj.$ref.split("/").at(-1)!;
      obj.$ref = `#/$defs/${definitionName}`;

      if (definitionName in definitions) {
        return;
      }

      const clonedDefinition = structuredClone(definition);
      definitions[definitionName] = clonedDefinition;
      collectDefinitions(clonedDefinition);
      return;
    }

    for (const value of Object.values(obj)) {
      collectDefinitions(value);
    }
  }

  collectDefinitions(inputSchema);
  inputSchema.$defs = definitions;
}

function resolveRef<Value extends SecurityScheme | SomeJSONSchema | Parameter>(
  spec: OpenApiSpec,
  ref: string,
): Value {
  const parts = ref.split("/").slice(1);

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  let current: any = spec;
  for (const part of parts) {
    current = current[part];
  }

  return current;
}

