import { describe, expect, it, test } from "vitest";
import type { ToolFilter } from "./toolFilters.ts";
import { getToolFilter, isToolAllowed } from "./toolFilters.ts";

test("getToolFilter", () => {
  expect(getToolFilter({})).toEqual({
    allowedTools: undefined,
    deniedTools: undefined,
  });

  expect(getToolFilter({ allowTools: ["foo"] })).toEqual({
    allowedTools: new Set(["foo"]),
    deniedTools: undefined,
  });
  expect(getToolFilter({ denyTools: ["foo"] })).toEqual({
    allowedTools: undefined,
    deniedTools: new Set(["foo"]),
  });
});

describe("isToolAllowed", () => {
  it("should allow all tools by default", () => {
    expect(isToolAllowed("foo")).toBe(true);
  });

  it("should allow denying tools", () => {
    const filter: ToolFilter = {
      deniedTools: new Set(["jafar"]),
    };
    expect(isToolAllowed("jafar", filter)).toBe(false);
    expect(isToolAllowed("iago", filter)).toBe(true);
  });

  it("should allow tools", () => {
    const filter: ToolFilter = {
      allowedTools: new Set(["muphasa"]),
    };
    expect(isToolAllowed("muphasa", filter)).toBe(true);
    expect(isToolAllowed("scar", filter)).toBe(false);
  });

  it("should deny custom methods by default", () => {
    expect(isToolAllowed("customGet")).toBe(false);
    expect(isToolAllowed("customPost")).toBe(false);
    expect(
      isToolAllowed("customPut", {
        // Even if allowed explicitely
        allowedTools: new Set(["customPut"]),
      }),
    ).toBe(false);
  });
});

import { afterAll, afterEach, beforeAll, beforeEach, describe, expect, it, vi } from "vitest";
import { Client } from "@modelcontextprotocol/sdk/client/index.js";

import { startServer } from "./start-server.ts";
import { InMemoryTransport } from "@modelcontextprotocol/sdk/inMemory.js";
import { setupServer } from "msw/node";
import { http } from "msw";
import { ZodError } from "zod";
import type { AppState } from "../appState.ts";
import { AppStateManager } from "../appState.ts";
import { REQUIRED_ACLS } from "../DashboardApi.ts";

const mswServer = setupServer();

beforeAll(() => mswServer.listen());
afterEach(() => mswServer.resetHandlers());
afterAll(() => mswServer.close());

describe("when specifying credentials flag", () => {
  it("should throw if params are missing", async () => {
    await expect(
      startServer({
        // @ts-expect-error -- I'm testing missing params
        credentials: { applicationId: "appId" },
      }),
    ).rejects.toThrow(ZodError);
    await expect(
      startServer({
        // @ts-expect-error -- I'm testing missing params
        credentials: { apiKey: "apiKey" },
      }),
    ).rejects.toThrow(ZodError);
  });

  it("should not throw if both params are provided", async () => {
    vi.spyOn(AppStateManager, "load").mockRejectedValue(new Error("Should not be called"));
    const server = await startServer({ credentials: { applicationId: "appId", apiKey: "apiKey" } });

    expect(AppStateManager.load).not.toHaveBeenCalled();

    await server.close();
  });

  it("should allow filtering tools", async () => {
    mswServer.use(
      http.put("https://appid.algolia.net/1/indexes/indexName/settings", () =>
        Response.json({ taskId: 123 }),
      ),
    );
    const client = new Client({ name: "test client", version: "1.0.0" });
    const server = await startServer({
      credentials: {
        apiKey: "apiKey",
        applicationId: "appId",
      },
      allowTools: ["setSettings"],
    });

    const [clientTransport, serverTransport] = InMemoryTransport.createLinkedPair();
    await Promise.all([client.connect(clientTransport), server.connect(serverTransport)]);

    const { tools } = await client.listTools();

    expect(tools).toHaveLength(1);
    expect(tools[0].name).toBe("setSettings");

    const result = await client.callTool({
      name: "setSettings",
      arguments: {
        indexName: "indexName",
        requestBody: {
          searchableAttributes: ["title"],
        },
      },
    });

    expect(result).toMatchInlineSnapshot(`
      {
        "content": [
          {
            "text": "{"taskId":123}",
            "type": "text",
          },
        ],
      }
    `);

    await server.close();
  });
});

